{
  "findings": [
    {
      "title": "Inconsistent number of planned cycles: Amendment 2 says corrected to be consistent, but Amendment 3 footnote says 16 cycles, while synopsis may state different (not shown).",
      "page": 15,
      "quote": "This pertains to patients who completed all 16 cycles of planned treatment",
      "severity": "major"
    },
    {
      "title": "Cross-reference to Section 8.1.2.1 for pemetrexed premedication, but Section 8.1.2.1 is titled 'Pemetrexed, Alimta®' and may not contain premedication details; also footnote says 'as per Section 8.1.2.1' but the premedication is likely in Section 8.2 Pretreatments.",
      "page": 15,
      "quote": "as per Section 8.1.2.1",
      "severity": "major"
    },
    {
      "title": "Inconsistent numbering of exclusion criteria: Amendment 1 adds #18 for idelalisib, Amendment 2 says revised #6,7,19,20 and added #21, but Amendment 3 says removed #10 (doxycycline) and kept number for formatting, leading to potential mismatch.",
      "page": 19,
      "quote": "Section 6.2.2 Exclusion Criteria #18",
      "severity": "major"
    },
    {
      "title": "Inconsistent definition of end of study: Amendment 2 says corrected length of study accrual and follow-up, but Amendment 3 says updated end of study definition; no actual definition provided in excerpt.",
      "page": 14,
      "quote": "The end of study definition was updated.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent timing of survival status check: Amendment 3 says deleted from Follow-up Visits 1 and 2, but Section 7.2.3 Survival Data Collection may still require it; not shown.",
      "page": 15,
      "quote": "Survival status check deleted from Follow-up Visits 1 and 2",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about missed doses: Amendment 3 says missed doses will not be made up, but Section 8.3.3 may allow resumption; not shown.",
      "page": 14,
      "quote": "Missed doses of study drug or visits will not be made up.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about rest period for irinotecan in Japan: Amendment 3 says at least 14 days rest, but Section 8.4.3 may have different window; not shown.",
      "page": 13,
      "quote": "there will be at least 14 days of rest before subsequent irinotecan administration.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about ECOG stratification: Amendment 2 says added as stratification factor, but Amendment 3 says Figure 2 revised to include ECOG stratification; no mention of whether it is used in analysis (Amendment 2 says not in primary model).",
      "page": 17,
      "quote": "Added Eastern Cooperative Oncology Group (ECOG) performance status as a stratification factor for randomization",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about anti-drug antibody wording: Amendment 2 says updated to be consistent with current practice, but Amendment 3 says footnote #12 updated ADA sample collection; no details.",
      "page": 17,
      "quote": "Updated anti-drug antibody wording to be consistent with current practice",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about exclusion of idelalisib: Amendment 1 adds #18, but Amendment 2 says revised #6,7,19,20 and added #21; #18 may be renumbered.",
      "page": 19,
      "quote": "An exclusion criterion has been added for the following reason:  Patients who have previously been treated with idelalisib will be excluded",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about AESI: Amendment 1 adds AESI for PI3K inhibitor, but Amendment 3 says MedDRA list updated; no mention of this AESI in Amendment 3.",
      "page": 19,
      "quote": "An irAE of any grade in a patient previously treated with a PI 3-K inhibitor.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent statement about end of treatment definition: Amendment 3 says added in text and deleted from Table 1, but Table 1 may still have footnote; not shown.",
      "page": 14,
      "quote": "The end of treatment definition was added in the text and deleted from Table 1",
      "severity": "minor"
    }
  ]
}
